import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        K = int(next(iterator))
        P = []
        for _ in range(K):
            P.append(int(next(iterator)))

        adj = [[] for _ in range(K)]
        for i in range(K):
            row = next(iterator)
            for j in range(K):
                if row[j] == 'Y':
                    adj[i].append(j)
    except StopIteration:
        return

    visited = [False] * K
    components = []

    for i in range(K):
        if not visited[i]:
            comp_indices = []
            queue = deque([i])
            visited[i] = True
            while queue:
                u = queue.popleft()
                comp_indices.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
            components.append(comp_indices)

    result = [0] * K
    for comp in components:
        values = []
        indices = sorted(comp)
        for idx in indices:
            values.append(P[idx])
        values.sort()
        for i, idx in enumerate(indices):
            result[idx] = values[i]

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    solve()
